variables.decision:
{# A failed radio send is separate from MQTT acceptance. Store only known logical
   fixtures; coalesce channel errors, then retry one current fixture per tick. #}
{% set now_s=as_timestamp(now()) %}
{% set prior=state_attr('sensor.ls_effects_runtime','transport_recovery') or {} %}
{% set targets=state_attr('sensor.ls_effects_runtime','targets') or {} %}
{% set power=state_attr('sensor.ls_overrides','power') or {} %}
{% set n=namespace(ledger={},matched=[],retry='',notices=[],eligible=[]) %}
{% for L,t in targets.items() if L in catalog.members and not t.get('is_room',false) %}
 {% if is_state(L,'on') and t.get('on',false) and power.get(t.get('area'),true)
       and t.get('brightness',{}).get('kind')=='constant'
       and t.get('color',{}).get('kind')=='constant' %}
  {% set n.eligible=n.eligible+[L] %}
 {% endif %}
{% endfor %}
{% for L,r in prior.items() if L in catalog.members and r is mapping %}
 {% if r.get('window_start') is number and r.get('attempts') is number and r.get('due') is number %}
  {% set n.ledger=dict(n.ledger,**{L:r}) %}
 {% endif %}
{% endfor %}
{% if trigger.id=='failure' %}
 {% set names=trigger.payload_json.get('message','')  | regex_findall("^(?:z2m: )?Publish 'set' '(?:color_temp|color|brightness|state)' to '([^']+)' failed:") %}
 {% if names %}
  {% set topic='zigbee2mqtt/'~names[0]~'/set' %}
  {% set endpoints=namespace(ids=[]) %}
  {% for E,T in catalog.topics.items() if T==topic %}{% set endpoints.ids=endpoints.ids+[E] %}{% endfor %}
  {% for group in catalog.multicast if group.get('verified',false) and group.topic==topic %}
   {% set endpoints.ids=endpoints.ids+(group.members|list) %}
  {% endfor %}
  {# Z2M logs a device's current friendly name even when the command used IEEE.
     Resolve its integration-supplied name only when it identifies one endpoint. #}
  {% if not endpoints.ids %}
   {% set named=namespace(ids=[]) %}
   {% for E in catalog.topics if device_attr(E,'name')==names[0] %}
    {% set named.ids=named.ids+[E] %}
   {% endfor %}
   {% if named.ids|count==1 %}{% set endpoints.ids=named.ids %}{% endif %}
  {% endif %}
  {% for L,members in catalog.members.items() if L in n.eligible %}
   {% if members|select('in',endpoints.ids)|list|count>0 %}{% set n.matched=n.matched+[L] %}{% endif %}
  {% endfor %}
 {% endif %}
 {% for L in n.matched %}
  {% set r=n.ledger.get(L,{}) %}
  {% if not r or now_s-r.window_start>=300 %}
   {% set r={'window_start':now_s,'attempts':0,'due':now_s+3,'pending':false,'notified':false} %}
  {% endif %}
  {% if r.attempts>=3 %}
   {% if not r.get('notified',false) %}{% set n.notices=n.notices+[L] %}{% endif %}
   {% set r=dict(r,pending=false,notified=true) %}
  {% else %}
   {% set r=dict(r,pending=true,due=r.due if r.get('pending',false) else now_s+3) %}
  {% endif %}
  {% set n.ledger=dict(n.ledger,**{L:r}) %}
 {% endfor %}
{% elif is_state('binary_sensor.zigbee2mqtt_bridge_connection_state','on') %}
 {% set pick=namespace(lamp='',due=none) %}
 {% for L,r in n.ledger|dictsort if r.get('pending',false) %}
  {% if L not in n.eligible %}
   {% set n.ledger=dict(n.ledger,**{L:dict(r,pending=false)}) %}
  {% elif r.attempts>=3 %}
   {% if not r.get('notified',false) %}{% set n.notices=n.notices+[L] %}{% endif %}
   {% set n.ledger=dict(n.ledger,**{L:dict(r,pending=false,notified=true)}) %}
  {% elif r.due<=now_s and (pick.due is none or r.due<pick.due) %}
   {% set pick.lamp=L %}{% set pick.due=r.due %}
  {% endif %}
 {% endfor %}
 {% if pick.lamp %}
  {% set n.retry=pick.lamp %}{% set r=n.ledger[n.retry] %}
  {# Keep pending until HA accepts the render request. An API error leaves a
     bounded retry for the next tick; radio errors arrive through MQTT later. #}
  {% set n.ledger=dict(n.ledger,**{n.retry:dict(r,attempts=r.attempts+1,due=now_s+5)}) %}
 {% endif %}
{% endif %}
{{ {'ledger':n.ledger,'retry':n.retry,'notices':n.notices} }}
